mapper.select:
SELECT  COUNT(*)
  FROM  tdm50_chck_job
 WHERE  tdm50_company_id = #{companyId}
   AND  tdm50_check_ym > #{checkYm}

mapper.update:
UPDATE  tdm50_chck_job
   SET  tdm50_check_nm   = #{checkName}
     ,  tdm50_start_date = CAST(#{startDate} AS date)
     ,  tdm50_end_date   = CAST(#{endDate} AS date)
     ,  tdm50_upd_nm     = #{updName}
     ,  tdm50_upd_date   = f_sysdate()
 WHERE  tdm50_chck_job_id = #{chckJobId}
   AND  tdm50_company_id  = #{companyId}

mapper.select:
SELECT MAX(tdm50_check_ym)
  FROM tdm50_chck_job
 WHERE tdm50_company_id = #{companyId}
   AND tdm50_check_ym < #{checkYm}

